$dir="../uploads/blog/";if(!is_dir($dir))mkdir($dir,0777,true);$error="";
function slugify($s){$s=strtolower(trim($s));$s=preg_replace('/[^a-z0-9]+/','-',$s);return trim($s,'-');}
if(isset($_GET["delete"])){ $id=(int)$_GET["delete"];$q=$conn->prepare("SELECT image FROM blog_posts WHERE id=?");$q->bind_param("i",$id);$q->execute();$r=$q->get_result()->fetch_assoc();if($r&&!empty($r["image"])&&is_file($dir.$r["image"]))@unlink($dir.$r["image"]);$q=$conn->prepare("DELETE FROM blog_posts WHERE id=?");$q->bind_param("i",$id);$q->execute();header("Location:blog.php");exit;}
if($_SERVER["REQUEST_METHOD"]==="POST"){ $title=trim($_POST["title"]??"");$excerpt=trim($_POST["excerpt"]??"");$content=trim($_POST["content"]??"");$status=$_POST["status"]==="draft"?"draft":"published";if($title===""||$content==="")$error="Title and content are required.";else{$slug=slugify($title)."-".time();$image="";if(!empty($_FILES["image"]["name"])&&$_FILES["image"]["error"]===UPLOAD_ERR_OK){$type=mime_content_type($_FILES["image"]["tmp_name"]);$allowed=["image/jpeg","image/png","image/webp"];if(!in_array($type,$allowed))$error="Only JPG, PNG and WEBP images are allowed.";else{$ext=strtolower(pathinfo($_FILES["image"]["name"],PATHINFO_EXTENSION));$image=uniqid("blog_",true).".".$ext;move_uploaded_file($_FILES["image"]["tmp_name"],$dir.$image);}}if($error===""){ $q=$conn->prepare("INSERT INTO blog_posts(title,slug,excerpt,content,image,status) VALUES(?,?,?,?,?,?)");$q->bind_param("ssssss",$title,$slug,$excerpt,$content,$image,$status);$q->execute();header("Location:blog.php?added=1");exit;}}}
$posts=$conn->query("SELECT * FROM blog_posts ORDER BY id DESC");
